<?php require 'config.php';require_login();$s=db()->prepare('SELECT p.*,b.name branch_name FROM patients p JOIN branches b ON b.id=p.registered_branch_id WHERE p.id=?');$s->execute([(int)($_GET['id']??0)]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Pasien tidak ditemukan.');}if (!is_center() && (int)$p['registered_branch_id'] !== (int)user()['branch_id']) { http_response_code(403); exit('Anda tidak memiliki akses ke data pasien ini.'); }$s=db()->prepare('SELECT r.*,b.name branch_name FROM medical_records r JOIN branches b ON b.id=r.branch_id WHERE r.patient_id=? '.(is_center()?'':'AND r.branch_id='.(int)user()['branch_id']).' ORDER BY r.visit_date DESC');$s->execute([$p['id']]);$records=$s->fetchAll();layout_start('Rekam Medis');?><div class="card"><h1><?=e($p['full_name'])?></h1><p>No. RM: <b><?=e($p['medical_record_no'])?></b> · Terdaftar di: <?=e($p['branch_name'])?></p><p>NIK: <?=e($p['nik'])?> · Telepon: <?=e($p['phone'])?> · Tanggal lahir: <?=e($p['birth_date'])?></p><a class="btn" href="record_form.php?patient_id=<?=$p['id']?>">+ Catat kunjungan</a></div><div class="card"><h2>Riwayat Rekam Medis</h2><?php foreach($records as $r):?><article class="card"><b><?=e($r['visit_date'])?> · <?=e($r['branch_name'])?></b><p><b>Dokter:</b> <?=e($r['doctor_name'])?></p><p><b>Keluhan:</b> <?=nl2br(e($r['complaint']))?></p><p><b>Diagnosis:</b> <?=nl2br(e($r['diagnosis']))?></p><p><b>Tindakan:</b> <?=nl2br(e($r['treatment']))?></p><p><b>Resep:</b> <?=nl2br(e($r['prescription']))?></p><p><b>Catatan:</b> <?=nl2br(e($r['notes']))?></p></article><?php endforeach;if(!$records):?><p>Belum ada rekam medis.</p><?php endif;?></div><?php layout_end();?>

